package com.mo.economy_system.network;
import static org.junit.jupiter.api.Assertions.*;
import com.mo.economy_system.common.network.InvitePlayerMessage;import io.netty.buffer.Unpooled;import io.netty.handler.codec.DecoderException;import java.util.UUID;import net.minecraft.network.FriendlyByteBuf;import org.junit.jupiter.api.Test;
class TerritoryInviteWireCodecTest{@Test void goldenAndRoundTrip(){InvitePlayerMessage m=new InvitePlayerMessage(UUID.fromString("00112233-4455-6677-8899-aabbccddeeff"),UUID.fromString("ffeeddcc-bbaa-9988-7766-554433221100"));FriendlyByteBuf b=new FriendlyByteBuf(Unpooled.buffer());TerritoryInviteWireCodec.encode(m,b);assertEquals(32,b.readableBytes());assertEquals("00112233445566778899aabbccddeeffffeeddccbbaa99887766554433221100",hex(b.copy()));assertEquals(m,TerritoryInviteWireCodec.decode(b));}@Test void rejectsTruncationAndTrailing(){for(int n:new int[]{0,15,16,31}){FriendlyByteBuf b=new FriendlyByteBuf(Unpooled.buffer());b.writeZero(n);assertThrows(DecoderException.class,()->TerritoryInviteWireCodec.decode(b));}FriendlyByteBuf b=new FriendlyByteBuf(Unpooled.buffer());TerritoryInviteWireCodec.encode(new InvitePlayerMessage(UUID.randomUUID(),UUID.randomUUID()),b);b.writeByte(1);assertThrows(DecoderException.class,()->TerritoryInviteWireCodec.decode(b));}private static String hex(io.netty.buffer.ByteBuf b){StringBuilder s=new StringBuilder();while(b.isReadable())s.append(String.format("%02x",b.readUnsignedByte()));return s.toString();}}
